  'Geography': [ { label: 'NCERT Geography textbooks (eBooks portal)', url: 'https://ncert.nic.in/textbook.php' } ],
  'History': [ { label: 'NCERT History textbooks', url: 'https://ncert.nic.in/textbook.php' } ],
